.mist--theme-identity-title {
  background: var(--mist--theme-title-highlight-gradient);
  font-family: "Bebas Neue", sans-serif !important;
  margin: 0;
  padding-left: 0.1em;
  padding-top: 0.1em;
}
.mist--theme-identity-text {
  display: inline-block;
  position: relative;
  width: 100%;
  min-height: 2em;
  font-family: "Caveat", "Labrada", sans-serif;
  line-height: 1em;
  font-size: var(--h3-size);
  background: var(--mist--theme-content-highlight-gradient);
}
.mist--theme-identity-text {
  position: relative;
  display: block;
  width: 100%;
  min-height: 2em;
  background: var(--mist--theme-content-highlight-gradient);
  font-family: "Caveat", "Labrada", sans-serif;
  line-height: 1em;
  font-size: var(--h3-size);
  isolation: isolate;
}
.mist--theme-identity-text::after {
  content: "";
  position: absolute;
  margin-top: 1px;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  background-image: var(--mist--theme-city-dashed-underline-background-image);
  mask-image: repeating-linear-gradient(to bottom, transparent 0, transparent calc(1lh - var(--mist--theme-dashed-underline-thickness)), black calc(1lh - var(--mist--theme-dashed-underline-thickness)), black 1lh);
}/*
 * Caveat Font
 * This font is used for aside elements.
*/
@font-face {
  font-family: "Caveat";
  font-weight: normal;
  font-style: normal;
  src: url(data:font/ttf;base64,);
}
@font-face {
  font-family: "Caveat";
  font-weight: bold;
  font-style: normal;
  src: url(data:font/ttf;base64,);
}
.mist--theme-tag-line {
  display: inline-grid;
  grid-template-columns: 1.5em 1fr 1.5em;
  width: 100%;
  background: var(--mist--theme-city-dashed-underline);
  font-size: var(--font-text-size);
  line-height: var(--h3-size);
}
.mist--theme-tag-line.no-burn {
  grid-template-columns: 1.5em 1fr;
}
.mist--theme-tag-line.odd {
  background: var(--mist--theme-content-highlight-gradient), var(--mist--theme-city-dashed-underline);
}
.mist--theme-tag-line-question {
  border-right: 1px solid rgb(var(--mist--theme-city-accent)/0.6);
}
.mist--theme-tag-line-question-letter {
  position: relative;
  top: 0.15em;
  padding-left: 0.25em;
  font-family: "Caveat", "Labrada", sans-serif;
  font-size: var(--h3-size);
}
.mist--theme-tag-line-text {
  position: relative;
  padding-left: 0.25em;
  font-family: "Caveat", "Labrada", sans-serif;
  font-size: var(--h3-size);
  top: 0.2em;
}
.mist--theme-tag-line-burn {
  display: inline-flex;
  padding-bottom: 0.2em;
  align-items: end;
  justify-content: center;
}
.mist--theme-tag-line-burn > span > svg {
  fill: var(--mist--theme-city-icon-background-bright);
}/* 
