.mist--theme-tag-list {
  display: inline-flex;
  flex-direction: column;
  padding: 0 0.3em;
  font-size: var(--font-text-size);
}
.mist--theme-tag-list-header {
  display: inline-flex;
  flex-direction: row;
  justify-content: space-between;
}
.mist--theme-tag-list-header-title {
  background: var(--mist--theme-title-highlight-gradient);
  font-family: "Bebas Neue", sans-serif !important;
  margin: 0;
  padding-left: 0.1em;
  padding-top: 0.1em;
}
.mist--theme-tag-list-header-burn {
  padding-bottom: 0.3rem;
  font-size: 0.7em;
  line-height: 8px;
  text-align: center;
  font-family: "Fira Sans Extra Condensed", sans-serif;
  align-self: self-end;
}.mist--theme {
  display: flex;
  flex-direction: column;
  row-gap: 0.5em;
  border-radius: var(--radius-s);
  width: 100%;
}
.mist--theme-border {
  height: fit-content;
  padding: 0.4em;
  border-radius: var(--radius-m);
  background-color: var(--mist--theme-city-border);
}
.mist--theme.city {
  background: var(--mist--theme-city-background);
  color: var(--mist--theme-city-text);
}
.mist--theme.otherscape {
  background: var(--mist--theme-otherscape-background);
}
.mist--theme.legend {
  background: var(--mist--theme-legend-background);
}.mist--theme-collection {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr 1fr;
}/*$vite$:1*/